=== submission_06.ino ===
   1| /*
   2|   Lab 3 - Hardware PWM
   3|   1 kHz square wave, 25% duty, on D5.
   4| 
   5|   D5 = P1.13
   6| 
   7|   PWM peripheral clock: 16 MHz
   8|   PRESCALER = DIV_16 -> 1 MHz, 1 us resolution
   9|   COUNTERTOP = 1000  -> 1000 us period = 1 kHz
  10|   compare    = 250   -> 250 us high = 25 %
  11| 
  12|   The duty value is constant so I made the table const.
  13| */
  14| 
  15| #include <Arduino.h>
  16| 
  17| static const uint16_t PWM_TABLE[] = { 250 | 0x8000 };
  18| 
  19| void setup() {
  20|   NRF_PWM3->PSEL.OUT[0] = (1UL << PWM_PSEL_OUT_PORT_Pos) | (13UL << PWM_PSEL_OUT_PIN_Pos);
  21| 
  22|   NRF_PWM3->ENABLE     = PWM_ENABLE_ENABLE_Enabled;
  23|   NRF_PWM3->MODE       = PWM_MODE_UPDOWN_Up;
  24|   NRF_PWM3->PRESCALER  = PWM_PRESCALER_PRESCALER_DIV_16;
  25|   NRF_PWM3->COUNTERTOP = 1000;
  26|   NRF_PWM3->LOOP       = 0;
  27|   NRF_PWM3->DECODER    = (PWM_DECODER_LOAD_Common << PWM_DECODER_LOAD_Pos) |
  28|                          (PWM_DECODER_MODE_RefreshCount << PWM_DECODER_MODE_Pos);
  29| 
  30|   NRF_PWM3->SEQ[0].PTR      = (uint32_t)PWM_TABLE;
  31|   NRF_PWM3->SEQ[0].CNT      = sizeof(PWM_TABLE) / sizeof(PWM_TABLE[0]);
  32|   NRF_PWM3->SEQ[0].REFRESH  = 0;
  33|   NRF_PWM3->SEQ[0].ENDDELAY = 0;
  34| 
  35|   NRF_PWM3->TASKS_SEQSTART[0] = 1;
  36| }
  37| 
  38| void loop() {
  39| }
</student_code>
